<?= $this->include('layouts/header') ?>
<div class="page-head"><div><div class="page-kicker">Gate desk</div><h1 class="page-title">Security desk</h1><p class="page-subtitle">Register incoming papers, verify extracted information, and hand clean receipts into inventory.</p></div><div class="head-actions"><?php if($canVisitor): ?><a class="btn primary" href="<?=site_url('security/visitors')?>">👤 Visitor Register</a><?php endif; ?><?php if($canScan): ?><a class="btn primary" href="<?=site_url('security/scan')?>">⌁ Scan / upload</a><?php endif; ?><?php if($canManual): ?><a class="btn" href="<?=site_url('security/manual')?>">✎ Manual entry</a><?php endif; ?></div></div>
<div class="grid grid-3" style="margin-bottom:18px"><div class="card metric"><div class="metric-label">Today's entries</div><div class="metric-value"><?=number_format(count($documents))?></div><div class="metric-note">Gate documents</div></div><div class="card metric"><div class="metric-label">Verified</div><div class="metric-value"><?=number_format(count(array_filter($documents,fn($d)=>(int)$d['verified']===1)))?></div><div class="metric-note good">Posted into inventory</div></div><div class="card metric"><div class="metric-label">Needs review</div><div class="metric-value"><?=number_format(count(array_filter($documents,fn($d)=>(int)$d['verified']!==1)))?></div><div class="metric-note warn">Verification required</div></div></div>

<?php if($canVisitor): ?>
<div class="card" style="margin-bottom:18px"><div class="section-head"><div><h2 class="section-title">Visitor register</h2><div class="section-meta">General visitors are logged immediately. Owner meetings stay pending until the selected owner approves.</div></div><a class="btn small primary" href="<?=site_url('security/visitors')?>">Open Visitor Register</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Entry</th><th>Visitor</th><th>Purpose</th><th>To meet</th><th>Status</th></tr></thead><tbody><?php if(empty($visitorRows)): ?><tr><td colspan="5"><div class="empty"><strong>No visitors yet</strong>Use Visitor Register to record the first gate entry.</div></td></tr><?php else: foreach($visitorRows as $v): ?><tr><td><?=esc($v['entry_at'])?></td><td><div style="display:flex;align-items:center;gap:9px"><?php if(!empty($v['photo_path'])): ?><img src="<?=site_url('security/visitors/'.$v['id'].'/photo')?>" alt="" style="width:34px;height:34px;border-radius:50%;object-fit:cover;border:1px solid #ddd"><?php endif; ?><strong><?=esc($v['name'])?></strong></div></td><td><?=esc($v['purpose'] ?: '—')?></td><td><?=esc($v['owner_name'] ?: '—')?></td><td><span class="badge <?=$v['status']==='APPROVED'||$v['status']==='CHECKED_IN'?'success':($v['status']==='PENDING'?'warning':'danger')?>"><?=esc($v['status'])?></span></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<?php endif; ?>
<div class="card"><div class="section-head"><div><h2 class="section-title">Today's incoming register</h2><div class="section-meta">Newest gate entries first</div></div><a class="btn small" href="<?=site_url('security/history')?>">Full history</a></div><div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Document</th><th>Guard</th><th>OCR</th><th>Transaction</th><th>Status</th><th></th></tr></thead><tbody><?php if(!$documents): ?><tr><td colspan="7"><div class="empty"><strong>No incoming documents today</strong>Scan a paper or create a manual entry to start the register.</div></td></tr><?php else: foreach($documents as $d): ?><tr><td><?=esc($d['created_at'])?></td><td><strong><?=esc($d['original_filename']??'Manual entry')?></strong></td><td><?=esc($d['guard_name']??'—')?></td><td><span class="badge <?=$d['ocr_status']==='completed'?'success':($d['ocr_status']==='unavailable'?'warning':'neutral')?>"><?=esc($d['ocr_status'])?></span></td><td class="mono"><?=esc($d['transaction_no']??'Pending')?></td><td><span class="badge <?=$d['verified']?'success':'warning'?>"><?=$d['verified']?'Verified':'Needs review'?></span></td><td><?php if(!$d['verified'] && !empty($d['id'])): ?><a class="btn small" href="<?=site_url('security/scan/'.$d['id'])?>">Review</a><?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div>
<?= $this->include('layouts/footer') ?>